            titleStyle.paragraphSpacing = style.titleSpacing
            titleStyle.lineBreakStrategy = ReaderPageLayoutEngine.lineBreakStrategy
            titleStyle.alignment = .natural
            output.append(NSAttributedString(
                string: title + "\n",
                attributes: [
